// Walks the live app._scene (built by @splinetool/runtime) and serializes a
// normalized description of hierarchy/transforms/cameras/lights/geometry,
// classifying each mesh's geometry as box/cylinder/rectangle/ellipse
// (translatable to code) or "baked" (SubdivGeometry/VectorGeometry, which
// scripts/bake-geometry.mjs -- run from THIS SAME page load, see below --
// exports to public/models/body.glb instead).
//
// Deliberately loads /bake.html, not /: geometry.uuid is randomly
// regenerated by @splinetool/runtime on every independent page load, so if
// this script and the geometry bake ran as two separate page.goto()s, the
// "baked" classification's geometryUuid here would never match the node
// names the bake wrote into body.glb. Both must read from one shared
// Application load. bake.html's src/bake/main.js exposes window.__app the
// same way index.html's src/main.js does, plus runs the bake automatically
// on load (see scripts/bake-geometry.mjs for how its output gets read back).
import { chromium } from 'playwright';
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'generated');
mkdirSync(outDir, { recursive: true });

const PRIMITIVE_GEOMETRY_TYPES = new Set(['CubeGeometry', 'CylinderGeometry']);

const browser = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (err) => console.error('[pageerror]', err));

await page.goto('http://127.0.0.1:5173/bake.html', { waitUntil: 'load' });
await page.waitForFunction(() => window.__splineLoaded === true, { timeout: 20000 });
await page.waitForTimeout(300);

const description = await page.evaluate((primitiveTypesArr) => {
  const app = window.__app;
  const scene = app._scene;
  const primitiveTypes = new Set(primitiveTypesArr);

  function vec3(v) {
    return v ? [v.x, v.y, v.z] : [0, 0, 0];
  }

  // Cloner-generated instances (e.g. the ring of neck screws) share the same
  // compiled geometry.uuid/material.uuid as their authored template but have
  // no .data of their own. Build a geometry.uuid -> classification map from
  // whichever mesh DOES carry .data.geometry, then every mesh (template or
  // clone) looks itself up by geometry.uuid.
  const classificationByGeomUuid = new Map();

  function classifyFromData(dataGeom) {
    const type = dataGeom.type;
    if (type === 'CubeGeometry') {
      return {
        kind: 'box',
        width: dataGeom.width,
        height: dataGeom.height,
        depth: dataGeom.depth,
        widthSegments: dataGeom.widthSegments ?? 1,
        heightSegments: dataGeom.heightSegments ?? 1,
        depthSegments: dataGeom.depthSegments ?? 1,
        cornerRadius: dataGeom.cornerRadius ?? 0,
        cornerSegments: dataGeom.cornerSegments ?? 1,
      };
    }
    if (type === 'CylinderGeometry') {
      // Every cylinder in this scene has a nonzero cornerRadius, and
      // treating radiusTop/radiusBottom as literal THREE.CylinderGeometry
      // radii (phases 1-3's original approach) produced a collar piece
      // roughly 2.5x too wide compared to the live compiled geometry's own
      // bounding box. Tried to reverse-engineer the correct formula
      // (radiusTop/Bottom as a 0-100 percentage of width/2, matching the
      // Rectangle/Ellipse cornerRadius convention) but it fit one instance
      // and not another, and a third instance's local bounding box isn't
      // even circular in X/Z -- not confident enough in any formula to
      // trust it. When cornerRadius or hollow is nonzero, MUST_BAKE_CYLINDER
      // below routes this to the 'baked' path (same as organic geometry)
      // instead of guessing; only a plain cornerRadius=0, hollow=0 cylinder
      // (none exist in this scene, but might in another) uses literal
      // THREE.CylinderGeometry radii.
      const cornerRadius = dataGeom.cornerRadius ?? 0;
      const hollow = dataGeom.hollow ?? 0;
      if (cornerRadius || hollow) {
        return {
          kind: 'baked',
          originalType: 'CylinderGeometry',
          note: `cornerRadius=${cornerRadius}/hollow=${hollow} nonzero -- radiusTop/radiusBottom aren't literal units in that case and no reliable conversion formula was found, baked instead of guessed`,
        };
      }
      return {
        kind: 'cylinder',
        radiusTop: dataGeom.radiusTop,
        radiusBottom: dataGeom.radiusBottom,
        height: dataGeom.height,
        radialSegments: dataGeom.radialSegments ?? 12,
        heightSegments: dataGeom.heightSegments ?? 1,
        openEnded: !!dataGeom.openEnded,
        thetaStart: dataGeom.thetaStart ?? 0,
        thetaLength: dataGeom.thetaLength ?? 360,
        cornerRadius: 0,
        cornerSegments: dataGeom.cornerSegments ?? 1,
        hollow: 0,
      };
    }
    if (type === 'RectangleGeometry') {
      return {
        kind: 'rectangle',
        width: dataGeom.width,
        height: dataGeom.height,
        depth: dataGeom.depth,
        // percentage 0-100 of min(width,height)/2, not an absolute length
        cornerRadius: dataGeom.cornerRadius ?? [0, 0, 0, 0],
        cornerType: dataGeom.cornerType ?? 0, // 0 = rounded (arc), 1 = chamfered (straight cut)
        extrudeBevelSize: dataGeom.extrudeBevelSize ?? 0,
        extrudeBevelSegments: dataGeom.extrudeBevelSegments ?? 1,
      };
    }
    if (type === 'EllipseGeometry') {
      return {
        kind: 'ellipse',
        width: dataGeom.width,
        height: dataGeom.height,
        depth: dataGeom.depth,
        spikes: dataGeom.spikes ?? 32, // polygon point count (low-poly look), or star points if innerRadius > 0
        angle: dataGeom.angle ?? 360,
        innerRadius: dataGeom.innerRadius ?? 0,
        extrudeBevelSize: dataGeom.extrudeBevelSize ?? 0,
        extrudeBevelSegments: dataGeom.extrudeBevelSegments ?? 1,
      };
    }
    if (type === 'SubdivGeometry' || type === 'VectorGeometry') {
      return {
        kind: 'baked',
        originalType: type,
        note: 'wasm-computed (SubdivGeometry) or bezier-path (VectorGeometry, the logo text) geometry -- baked to public/models/body.glb, not reconstructed as code',
      };
    }
    return {
      kind: 'deferred',
      originalType: type,
      note: 'unrecognized geometry type -- not handled by any phase yet',
    };
  }

  // Pass 1: collect classifications from every mesh that has .data.geometry.
  (function collect(obj) {
    if (obj.isMesh && obj.data?.geometry && obj.geometry?.uuid) {
      if (!classificationByGeomUuid.has(obj.geometry.uuid)) {
        classificationByGeomUuid.set(obj.geometry.uuid, classifyFromData(obj.data.geometry));
      }
    }
    (obj.children || []).forEach(collect);
  })(scene);

  function classifyGeometry(obj) {
    const byUuid = obj.geometry?.uuid && classificationByGeomUuid.get(obj.geometry.uuid);
    const classified = byUuid ?? {
      kind: 'deferred',
      originalType: obj.geometry?.type ?? 'Unknown',
      note: 'no .data.geometry on this mesh or any sibling sharing its geometry.uuid',
    };
    // Needed by the 'baked' kind to look itself up in the glTF exported by
    // scripts/bake-geometry.mjs (which names its exported nodes by this same
    // geometry.uuid). Harmless to include for other kinds too.
    return { ...classified, geometryUuid: obj.geometry?.uuid };
  }

  // Spline composes each object's world matrix as
  // parentWorld * hiddenMatrix * localTRS(position/rotation/scale) --
  // hiddenMatrix (from obj.data.hiddenMatrix) is an extra rig/IK offset
  // applied between an object and its parent that is NOT reflected in
  // obj.position/rotation/scale at all. Reading only position/rotation/
  // scale (as this script did before) is silently wrong for any object
  // with a non-identity hiddenMatrix -- confirmed by comparing
  // getWorldPosition() against a hand-derived composition; every joint in
  // the arm/leg/neck chain has one, which is why the naive approach
  // rendered the whole robot in a completely wrong pose. Bake hiddenMatrix
  // into an "effective" local position/rotation/scale here so the rest of
  // this script (and generate-scene.mjs) can stay a straightforward
  // position/rotation/scale pipeline.
  function effectiveTRS(obj) {
    const hiddenMatrixArr = obj.data?.hiddenMatrix;
    if (!hiddenMatrixArr) {
      return {
        position: vec3(obj.position),
        rotation: obj.rotation ? [obj.rotation.x, obj.rotation.y, obj.rotation.z] : [0, 0, 0],
        scale: vec3(obj.scale),
      };
    }
    const hidden = new window.THREE.Matrix4().fromArray(hiddenMatrixArr);
    const effective = hidden.multiply(obj.matrix);
    const pos = new window.THREE.Vector3();
    const quat = new window.THREE.Quaternion();
    const scl = new window.THREE.Vector3();
    effective.decompose(pos, quat, scl);
    const euler = new window.THREE.Euler().setFromQuaternion(quat, 'XYZ');
    return {
      position: [pos.x, pos.y, pos.z],
      rotation: [euler.x, euler.y, euler.z],
      scale: [scl.x, scl.y, scl.z],
    };
  }

  function describe(obj) {
    const trs = effectiveTRS(obj);
    const node = {
      name: obj.name || '',
      objectType: obj.isMesh
        ? 'Mesh'
        : obj.isLight
          ? 'Light'
          : obj.isCamera
            ? 'Camera'
            : obj.type === 'Scene'
              ? 'Scene'
              : 'Group',
      position: trs.position,
      rotation: trs.rotation,
      scale: trs.scale,
      visible: obj.visible !== false,
    };

    if (obj.isCamera) {
      node.camera = {
        cameraType: obj.isOrthographicCamera ? 'OrthographicCamera' : 'PerspectiveCamera',
        fov: obj.fov,
        near: obj.near,
        far: obj.far,
      };
    }

    if (obj.isLight) {
      node.light = {
        lightType: obj.type,
        color: obj.color ? [obj.color.r, obj.color.g, obj.color.b] : [1, 1, 1],
        intensity: obj.intensity,
        distance: obj.distance,
        decay: obj.decay,
        angle: obj.angle,
        penumbra: obj.penumbra,
      };
    }

    if (obj.isMesh) {
      node.geometry = classifyGeometry(obj);
      // obj.material.uuid stays equal to the shared material's authoring
      // uuid even on clones that lack their own .data, so prefer it over
      // obj.data?.material.
      const mat = Array.isArray(obj.material) ? obj.material[0] : obj.material;
      node.materialId = mat?.uuid ?? obj.data?.material ?? null;
      node.castShadow = !!obj.castShadow;
      node.receiveShadow = !!obj.receiveShadow;
    }

    node.children = (obj.children || []).map(describe);
    return node;
  }

  const tree = describe(scene);

  function countGeomKinds(node, acc = {}) {
    if (node.geometry) acc[node.geometry.kind] = (acc[node.geometry.kind] || 0) + 1;
    (node.children || []).forEach((c) => countGeomKinds(c, acc));
    return acc;
  }

  return {
    tree,
    stats: countGeomKinds(tree),
  };
}, [...PRIMITIVE_GEOMETRY_TYPES]);

writeFileSync(join(outDir, 'scene-description.json'), JSON.stringify(description, null, 2));
console.log('Geometry kind counts:', description.stats);
console.log('Wrote generated/scene-description.json');

// --- Geometry bake (same page/app instance as above, see the header
// comment for why this can't be a separately-run script) ---
await page.waitForFunction(() => window.__bakeReady === true, { timeout: 30000 });
const { bakeError, base64, manifest } = await page.evaluate(() => ({
  bakeError: window.__bakeError,
  base64: window.__bakedGLBBase64,
  manifest: window.__bakeManifest,
}));

if (bakeError) {
  console.error('Bake failed:', bakeError);
  await browser.close();
  process.exit(1);
}

mkdirSync(join(root, 'public', 'models'), { recursive: true });
writeFileSync(join(root, 'public', 'models', 'body.glb'), Buffer.from(base64, 'base64'));
writeFileSync(join(outDir, 'bake-manifest.json'), JSON.stringify(manifest, null, 2));

const totalVerts = manifest.reduce((sum, m) => sum + m.vertexCount, 0);
console.log(
  `Baked ${manifest.length} unique geometries (${totalVerts} total vertices) -> public/models/body.glb`
);

await browser.close();
